    if (lib.uniffi_opentune_ffi_checksum_func_find_maps() != 59433.toShort()) {
        throw RuntimeException("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
    if (lib.uniffi_opentune_ffi_checksum_func_flash() != 6664.toShort()) {
