/**
 * Every fallible FFI call returns this. It carries a single human-readable
 * message (the underlying `opentune_core::Error`, an I/O error, or a decode
 * error), which is what a mobile UI wants to show the operator.
 */
sealed class OpenTuneException: kotlin.Exception() {
    
    /**
     * A file could not be read or written.
     */
    class Io(
        
        val `msg`: kotlin.String
        ) : OpenTuneException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    /**
     * An ECU definition, map, or checksum algorithm was not found.
     */
    class NotFound(
        
        val `msg`: kotlin.String
        ) : OpenTuneException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    /**
     * The image, definition JSON, or an argument was malformed.
     */
    class Invalid(
        
        val `msg`: kotlin.String
        ) : OpenTuneException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    /**
     * A core/driver/flash operation failed (safety gate, verify, decode …).
     */
    class Op(
        
        val `msg`: kotlin.String
        ) : OpenTuneException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<OpenTuneException> {
        override fun lift(error_buf: RustBuffer.ByValue): OpenTuneException = FfiConverterTypeOpenTuneError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeOpenTuneError : FfiConverterRustBuffer<OpenTuneException> {
    override fun read(buf: ByteBuffer): OpenTuneException {
        

        return when(buf.getInt()) {
            1 -> OpenTuneException.Io(
                FfiConverterString.read(buf),
                )
            2 -> OpenTuneException.NotFound(
                FfiConverterString.read(buf),
                )
            3 -> OpenTuneException.Invalid(
                FfiConverterString.read(buf),
                )
            4 -> OpenTuneException.Op(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: OpenTuneException): ULong {
        return when(value) {
            is OpenTuneException.Io -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is OpenTuneException.NotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is OpenTuneException.Invalid -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is OpenTuneException.Op -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
        }
    }

    override fun write(value: OpenTuneException, buf: ByteBuffer) {
        when(value) {
            is OpenTuneException.Io -> {
                buf.putInt(1)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is OpenTuneException.NotFound -> {
                buf.putInt(2)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is OpenTuneException.Invalid -> {
                buf.putInt(3)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is OpenTuneException.Op -> {
                buf.putInt(4)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




