public object FfiConverterSequenceTypeRegion: FfiConverterRustBuffer<List<Region>> {
    override fun read(buf: ByteBuffer): List<Region> {
        val len = buf.getInt()
        return List<Region>(len) {
            FfiConverterTypeRegion.read(buf)
        }
    }

    override fun allocationSize(value: List<Region>): ULong {
        val sizeForLength = 4UL
        val sizeForItems = value.map { FfiConverterTypeRegion.allocationSize(it) }.sum()
        return sizeForLength + sizeForItems
    }

    override fun write(value: List<Region>, buf: ByteBuffer) {
        buf.putInt(value.size)
        value.iterator().forEach {
            FfiConverterTypeRegion.write(it, buf)
        }
    }
}




